//! Replay of journals written by released v0.2.0 (owner decision 2026-11-01, item 3: in-place
//! upgrade from v0.2 is kept). Feature 037 changed what the engine *decides*: a negative lookup now
//! waits for review, an unknown outcome is never retried by an operator nor compensated
//! defensively. It did not change what an already committed journal *means*: replay never
//! re-evaluates a committed choice (ADR-0030 §15), so these v0.2 journals must still replay, and an
//! in-flight v0.2 run must continue under the current engine.
//!
//! The journals below were generated by running the v0.2.0 domain itself (tag `v0.2.0`, scenarios
//! `L1`..`L4`) and printing each event; they are not hand-written approximations.
#![allow(clippy::expect_used)]

mod common;

use std::collections::BTreeMap;
use std::time::Duration;

use common::{Harness, T0, activity, build, effect, id, saga};
use sagat_domain::execution::{
    FailureCode, Fence, PlannedEntry, ReconcileResult, RunEvent, RunId, RunState, RunStatus,
    StepStatus, StopReason,
};
use sagat_domain::saga::{ReconcileVerdict, SagaOutcome};
use sagat_domain::workflow::{NodeId, WorkflowDefinition};

fn n(s: &str) -> NodeId {
    NodeId::parse_stored(s).expect("stored node id")
}

fn c(s: &str) -> FailureCode {
    FailureCode::parse(s).expect("failure code")
}

fn replay(journal: &[RunEvent]) -> RunState {
    let run = RunId::generate();
    let state = RunState::replay(run, journal).expect("a v0.2 journal replays");
    assert_eq!(
        RunState::replay(run, journal).expect("replays again"),
        state,
        "replay is deterministic"
    );
    state
}

/// Continues a replayed v0.2 prefix with the current engine's commands.
fn resume(def: WorkflowDefinition, journal: &[RunEvent], now: time::OffsetDateTime) -> Harness {
    Harness {
        def,
        state: replay(journal),
        journal: journal.to_vec(),
        now,
        pending: None,
        children: BTreeMap::new(),
    }
}

